import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.ClgMjOt7.js";const u=JSON.parse('{"title":"ライブ壁紙 & ウィジェット","description":"ライブ壁紙サービスとホーム画面用ウィジェットの仕様","frontmatter":{"title":"ライブ壁紙 & ウィジェット","description":"ライブ壁紙サービスとホーム画面用ウィジェットの仕様"},"headers":[],"relativePath":"features/wallpaper-widget.md","filePath":"features/wallpaper-widget.md","lastUpdated":1786166106000}'),o={name:"features/wallpaper-widget.md"};function d(t,e,c,p,n,s){return l(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ライブ壁紙-ウィジェット" tabindex="-1">ライブ壁紙 &amp; ウィジェット <a class="header-anchor" href="#ライブ壁紙-ウィジェット" aria-label="Permalink to &quot;ライブ壁紙 &amp; ウィジェット&quot;">​</a></h1><p>Android システム機能と連携したライブ壁紙サービスおよびウィジェットの仕様です。</p><hr><h2 id="ライブ壁紙サービス-pallerialivewallpaperservice" tabindex="-1">ライブ壁紙サービス (<code>PalleriaLiveWallpaperService</code>) <a class="header-anchor" href="#ライブ壁紙サービス-pallerialivewallpaperservice" aria-label="Permalink to &quot;ライブ壁紙サービス (`PalleriaLiveWallpaperService`)&quot;">​</a></h2><p>端末の壁紙としてイラストを定期的に切り替えて表示する Android LiveWallpaper サービスです。</p><h3 id="設定パラメータ-appsettings" tabindex="-1">設定パラメータ (<code>AppSettings</code>) <a class="header-anchor" href="#設定パラメータ-appsettings" aria-label="Permalink to &quot;設定パラメータ (`AppSettings`)&quot;">​</a></h3><ul><li><code>liveWallpaperSource</code>: ソースの選択 (<code>all</code> / <code>bookmarks</code> / <code>folder</code>)</li><li><code>liveWallpaperIntervalMinutes</code>: 切り替え間隔（分単位。デフォルト 60 分）</li><li><code>liveWallpaperOrder</code>: 再生順序 (<code>random</code> / <code>order</code>)</li><li><code>liveWallpaperScaleMode</code>: 画面フィット方式 (<code>cover</code> / <code>fit</code>)</li><li><code>liveWallpaperCrossfade</code>: 画像切り替え時のクロスフェード遷移 (Boolean)</li><li><code>liveWallpaperExcludeSensitive</code>: センシティブ（R-18）作品の除外 (Boolean)</li></ul><hr><h2 id="ホーム画面ウィジェット" tabindex="-1">ホーム画面ウィジェット <a class="header-anchor" href="#ホーム画面ウィジェット" aria-label="Permalink to &quot;ホーム画面ウィジェット&quot;">​</a></h2><h3 id="_1-イラストウィジェット-illustwidgetprovider" tabindex="-1">1. イラストウィジェット (<code>IllustWidgetProvider</code>) <a class="header-anchor" href="#_1-イラストウィジェット-illustwidgetprovider" aria-label="Permalink to &quot;1. イラストウィジェット (`IllustWidgetProvider`)&quot;">​</a></h3><ul><li>お気に入り作品やランダムイラストをホーム画面に常時表示。</li><li>ウィジェットタップ時に Palleria アプリ内の該当イラスト詳細画面へ直接遷移。</li></ul><h3 id="_2-ランキングウィジェット-rankingwidgetprovider" tabindex="-1">2. ランキングウィジェット (<code>RankingWidgetProvider</code>) <a class="header-anchor" href="#_2-ランキングウィジェット-rankingwidgetprovider" aria-label="Permalink to &quot;2. ランキングウィジェット (`RankingWidgetProvider`)&quot;">​</a></h3><ul><li>今日の Pixiv デイリーランキング TOP 10 作品を取得し、スライド表示。</li><li>定期バックグラウンド更新により、最新データを維持。</li></ul>',13)])])}const v=a(o,[["render",d]]);export{u as __pageData,v as default};
